import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { clamp, ease } from "./helpers";
import '../index.css'

export default function TrustSection() {
  const sectionRef = useRef(null);
  const [p, setP] = useState(-1); // -1 = not yet in section

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      const scrolled = -rect.top;
      const total = el.offsetHeight - window.innerHeight;

      if (scrolled < 0 || scrolled > total) {
        setP(-1); // outside section
      } else {
        setP(scrolled / total);
      }
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const lp = (start, end) =>
    ease(clamp((p - start) / (end - start), 0, 1));

  const ghost1 = lp(0.05, 0.50);
  const ghost2 = lp(0.50, 0.95);

  // 110vh → -20vh as progress goes 0→1
  const g1Y = 110 - ghost1 * 130;
  const g2Y = 110 - ghost2 * 130;

  const isActive = p >= 0;

  const overlay = (
    <div style={{
      position: "fixed",
      inset: 0,
      pointerEvents: "none",
      zIndex: 9999,
      overflow: "hidden",
    }}>
      {/* Ghost 1 — LEFT */}
      <div style={{
        position: "absolute",
        left: "4%",
        top: 0,
        width: 300,
        transform: `translateY(${g1Y}vh)`,
        background: "rgba(230,230,230,0.95)",
        backdropFilter: "blur(12px)",
        borderRadius: 8,
        padding: "16px 22px",
        boxShadow: "0 4px 24px rgba(0,0,0,0.10)",
      }}>
        <p style={{
          fontSize: 14, color: "#343434", lineHeight: 1.7,
          fontFamily: "'Inter',sans-serif", margin: 0,
        }}>
          When speed and scale take priority, due diligence
          slips and blind spots widen. That's exactly what is
          happening in the gig economy today.
        </p>
      </div>

      {/* Ghost 2 — RIGHT */}
      <div style={{
        position: "absolute",
        right: "4%",
        top: 0,
        width: 300,
        transform: `translateY(${g2Y}vh)`,
        background: "rgba(230,230,230,0.95)",
        backdropFilter: "blur(12px)",
        borderRadius: 8,
        padding: "16px 22px",
        boxShadow: "0 4px 24px rgba(0,0,0,0.10)",
      }}>
        <p style={{
          fontSize: 14, color: "#343434", lineHeight: 1.7,
          fontFamily: "'Inter',sans-serif", margin: 0,
        }}>
          Identity swaps, impersonation, and hidden criminal
          histories do more than disrupt operations. They put
          safety, credibility, and customer trust at risk.
        </p>
      </div>
    </div>
  );

  return (
    <>
      {/* Portal renders directly into document.body — zero clipping risk */}
      {isActive && createPortal(overlay, document.body)}

      <div
        id="dots-png"
        ref={sectionRef}
        className="h-[280vh]"
        style={{ position: "relative" }}
      >
        <div style={{
          position: "sticky",
          top: 0,
          height: "100vh",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          overflow: "hidden",
          padding: "0 6vw",
        }}>

          <div style={{ position: "relative", textAlign: "center", zIndex: 1, lineHeight: 1.08 }}>

            <div>
              <span className="sm:text-[110px] text-[50px]" style={{
                fontFamily: "'Inter',sans-serif",
                fontWeight: 600, color: "#1A3BB0",
                display: "block", lineHeight: 1.0,
              }}>Trust,</span>
            </div>

            <div style={{ display: "flex", alignItems: "baseline", justifyContent: "center", gap: "0.2em", flexWrap: "wrap" }}>
              <span className="sm:text-[105px] text-[50px]" style={{
                fontFamily: "'Inter',sans-serif", fontWeight: 300, color: "#5D5D5D", lineHeight: 1.0,
              }}>however is  </span>
              <span className="sm:text-[105px] text-[50px]" style={{
                fontFamily: "'Inter',sans-serif", fontWeight: 700, color: "#343434", lineHeight: 1.05, marginLeft: "14px",
              }}>fragile.</span>
            </div>

            <div>
              <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 700, color: "#CE1010" }}>One </span>
              <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 400, color: "#5d5d5d" }}>news headline.</span>
            </div>

            <div>
              <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 700, color: "#CE1010" }}>One </span>
              <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 400, color: "#5d5d5d" }}>breach</span>
            </div>

            <div>
              <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 700, color: "#CE1010" }}>One </span>
              <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 400, color: "#5d5d5d" }}>bad experience.</span>
            </div>

            <div style={{ marginTop: 28 }}>
              <p style={{ fontSize: "20px", color: "#343434", lineHeight: 1.6, margin: 0 }}>
                is all it takes to undo years of hard-earned customer confidence.
              </p>
            </div>

          </div>
        </div>
      </div>
    </>
  );
}
